package agent

import (
	"context"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

// gitOpTimeout bounds each git plumbing call so a wedged git can never stall the
// mutating-build path. Worktree add/remove/diff are fast; this is a safety valve.
const gitOpTimeout = 60 * time.Second

// worktreeExec runs a seat's worker inside the given worktree dir and returns its
// SeatResult. In production it spawns claude in bypassPermissions mode; tests
// substitute a fake that writes files into dir. Decoupling the worker from the
// worktree lifecycle is what lets the mutating-build logic be tested with a fake
// runner and a real temp git repo — no `claude` process.
type worktreeExec func(ctx context.Context, dir string) SeatResult

// isGitRepo reports whether root is inside a git working tree.
func isGitRepo(ctx context.Context, root string) bool {
	if root == "" {
		return false
	}
	_, err := runGit(ctx, root, "rev-parse", "--is-inside-work-tree")
	return err == nil
}

// runMutatingBuild creates a FRESH throwaway git worktree of repoRoot at HEAD,
// invokes exec inside it (which may write real files), captures `git add -A` +
// `git diff --cached` as the seat's proposal, removes the worktree, and returns
// the result. The user's real working tree is never touched. On a git failure
// setting up the worktree it returns an error so the caller can degrade to the
// non-mutating propose-as-text path.
func runMutatingBuild(ctx context.Context, repoRoot, worktreeDir string, exec worktreeExec) (SeatResult, error) {
	if err := gitWorktreeAdd(ctx, repoRoot, worktreeDir); err != nil {
		return SeatResult{}, fmt.Errorf("worktree add: %w", err)
	}
	// Best-effort teardown even if ctx is already cancelled: use a detached context
	// so a cancelled round still removes the worktree rather than leaking it.
	defer gitWorktreeRemove(context.WithoutCancel(ctx), repoRoot, worktreeDir)

	res := exec(ctx, worktreeDir)

	diff, err := gitCaptureDiff(ctx, worktreeDir)
	switch {
	case err != nil:
		res.Warnings = append(res.Warnings, fmt.Sprintf("could not capture worktree diff: %v", err))
	case strings.TrimSpace(diff) == "":
		res.Warnings = append(res.Warnings, "mutating build produced no file changes; proposal is empty")
	default:
		// The captured diff is the authoritative proposal — it is what the worker
		// actually wrote, not what it claimed in its JSON.
		res.Proposal = diff
	}
	return res, nil
}

// gitWorktreeAdd creates a detached worktree at HEAD. --detach avoids inventing a
// branch name that could collide across parallel mutating seats. The leaf dir must
// not pre-exist (git creates it); we only ensure its parent exists.
func gitWorktreeAdd(ctx context.Context, repoRoot, worktreeDir string) error {
	if err := os.MkdirAll(filepath.Dir(worktreeDir), 0o700); err != nil {
		return err
	}
	_, err := runGit(ctx, repoRoot, "worktree", "add", "--detach", worktreeDir, "HEAD")
	return err
}

// gitCaptureDiff stages every change in the worktree (so NEW files are included)
// and returns the resulting diff. add -A only touches the throwaway worktree's
// index, never the caller's repo.
func gitCaptureDiff(ctx context.Context, worktreeDir string) (string, error) {
	if _, err := runGit(ctx, worktreeDir, "add", "-A"); err != nil {
		return "", err
	}
	out, err := runGit(ctx, worktreeDir, "diff", "--cached", "--no-color")
	if err != nil {
		return "", err
	}
	return string(out), nil
}

// gitWorktreeRemove tears down the worktree, falling back to prune + RemoveAll if
// the porcelain remove fails (e.g. the dir was already partly cleaned). It is
// best-effort: teardown failures are swallowed so they never fail a round.
func gitWorktreeRemove(ctx context.Context, repoRoot, worktreeDir string) {
	if _, err := runGit(ctx, repoRoot, "worktree", "remove", "--force", worktreeDir); err == nil {
		return
	}
	_, _ = runGit(ctx, repoRoot, "worktree", "prune")
	_ = os.RemoveAll(worktreeDir)
}

// runGit runs `git -C dir <args...>` under a bounded timeout and returns combined
// output on error for a useful message.
func runGit(ctx context.Context, dir string, args ...string) ([]byte, error) {
	tctx, cancel := context.WithTimeout(ctx, gitOpTimeout)
	defer cancel()
	full := append([]string{"-C", dir}, args...)
	cmd := exec.CommandContext(tctx, "git", full...)
	out, err := cmd.CombinedOutput()
	if err != nil {
		return out, fmt.Errorf("git %s: %w: %s", strings.Join(args, " "), err, strings.TrimSpace(string(out)))
	}
	return out, nil
}

