	}
	var meta runResultMeta
	stdout, stderr, timedOut, err := runWithReaping(ctx, cmd, timeout, &meta)
	return finalizeResult(spec, stdout, stderr, timedOut, err, meta, timeout)
}

// runMutating runs the build seat in a throwaway worktree so it can write real
// code, then captures the diff as the proposal. If the target is not a git repo,
// or worktree creation fails, it degrades to the non-mutating propose-as-text
// path with a warning — it never writes to the target's main working tree.
func (r ExecRunner) runMutating(ctx context.Context, spec SeatSpec, brief string, timeout time.Duration) SeatResult {
	if !isGitRepo(ctx, spec.RepoRoot) {
		res := r.runPlan(ctx, spec, brief, timeout)
		res.Warnings = append(res.Warnings,
			"mutating build unavailable: target is not a git repo; fell back to non-mutating propose-as-text")
		return res
	}

	worktreeDir := r.worktreePath(spec)
	res, err := runMutatingBuild(ctx, spec.RepoRoot, worktreeDir, func(wtCtx context.Context, dir string) SeatResult {
		cmd := BuildMutatingCmd(wtCtx, spec, brief, dir)
		var meta runResultMeta
		stdout, stderr, timedOut, cErr := runWithReaping(wtCtx, cmd, timeout, &meta)
		return finalizeResult(spec, stdout, stderr, timedOut, cErr, meta, timeout)
	})
